<template><div class="policy-desk"><WorkspaceHero eyebrow="POLICY DESK" title="制度问答与原文" description="先选适用学年，再围绕制度提问或追问。每次回答都保留原文、版本与来源，方便向教师核对。"/>
  <section class="card policy-toolbar"><label>适用学年 <el-select v-model="academicYear" aria-label="制度适用学年" @change="changeYear"><el-option v-for="y in years" :key="y" :label="y" :value="y"/></el-select></label><span>仅展示本人院系、年级和专业适用的当前发布版本</span><el-button @click="loadDocuments" :loading="loadingDocs">刷新制度目录</el-button></section>
  <div class="policy-layout"><section class="card conversation"><div class="desk-heading"><h2>带着问题查原文</h2><el-button text :disabled="asking" @click="clearConversation">新问题</el-button></div><p class="plain-note">本页采用原文检索与摘录，不调用大模型。原文没有规定的事项，会明确提示无法确认。</p>
    <div v-if="!turns.length" class="conversation-start"><span>从一条具体规则开始</span><h3>“志愿服务需要哪些证明？”</h3><p>继续追问“有效期呢？”时，会带上前面的主题关键词。</p><div><el-button v-for="sample in samples" :key="sample" plain @click="question=sample">{{sample}}</el-button></div></div>
    <article v-for="(turn,index) in turns" :key="index" class="policy-turn"><p class="question-record"><span>我的问题</span>{{turn.question}}</p><p>{{turn.result.answer}}</p><small v-if="turn.result.resolvedQuestion!==turn.question">本次查询主题：{{turn.result.resolvedQuestion}}</small><blockquote v-for="(citation,i) in turn.result.citations" :key="`${citation.resourceId}-${citation.paragraph}`"><div><strong>{{citation.title}}</strong><span>第 {{citation.paragraph}} 段 · v{{citation.revision}}</span></div><p>{{citation.quote}}</p><footer>{{citation.issuer}}<span v-if="citation.referenceNo"> · {{citation.referenceNo}}</span><el-button link type="primary" @click="openSource(turn.result.sources.find(s=>s.id===citation.resourceId))">查看全文与来源 ↗</el-button></footer></blockquote><p v-if="turn.result.limited" class="plain-note">目录超过单次读取范围，请联系维护人员归档历史内容或缩小制度范围。</p></article>
    <el-alert v-if="error" type="error" :title="error" :closable="false" show-icon/>
    <form class="policy-composer" @submit.prevent="ask"><label for="policy-question">你的问题或追问</label><el-input id="policy-question" v-model="question" type="textarea" :rows="3" maxlength="200" show-word-limit placeholder="输入成果名称、活动类型或想核对的条款" :disabled="asking"/><div><small>问答不认定资格、不自动加分，以完整制度及教师审核为准。</small><el-button native-type="submit" type="primary" :loading="asking" :disabled="!question.trim()">查询并引用原文</el-button></div></form>
  </section><aside class="card policy-directory" v-loading="loadingDocs"><div class="desk-heading"><h2>本期制度目录</h2><span>{{documents.length}} 份</span></div><el-alert v-if="directoryError" :title="directoryError" type="error" :closable="false"/><el-empty v-if="!loadingDocs&&!documents.length&&!directoryError" description="尚无适用于本人的已发布制度，请联系教师维护；可先查看模块规则。" :image-size="70"/><article v-for="doc in documents" :key="doc.id"><span>v{{doc.revision}} · {{doc.data.academicYear}}</span><h3>{{doc.data.title}}</h3><p>{{doc.data.summary||doc.data.issuer}}</p><small>生效 {{doc.data.effectiveFrom}}<template v-if="doc.data.effectiveTo"> 至 {{doc.data.effectiveTo}}</template></small><el-button link type="primary" @click="openSource(doc)">查看制度原文 →</el-button></article><router-link to="/rule-guide">另查管理员配置的模块规则 →</router-link></aside></div>
  <el-dialog v-model="sourceVisible" title="制度原文与来源" width="min(850px,95vw)" destroy-on-close><template v-if="source"><h2>{{source.data.title}}</h2><p>{{source.data.issuer}} · {{source.data.referenceNo||'未录入文号'}} · 版本 {{source.revision}}</p><p>适用学年 {{source.data.academicYear}} · 生效 {{source.data.effectiveFrom}}<template v-if="source.data.effectiveTo"> 至 {{source.data.effectiveTo}}</template></p><a v-if="safeHttps(source.data.sourceUrl)" :href="source.data.sourceUrl" target="_blank" rel="noopener noreferrer">打开来源页面 ↗</a><p class="source-body">{{source.data.body}}</p><p class="plain-note">这是查询时引用的发布版本。重新提问会查询当前有效版本，旧回答保留其当时的版本标识。</p></template></el-dialog>
</div></template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import WorkspaceHero from '@/components/WorkspaceHero.vue';import {getPolicies,askGuidance} from '@/api/guidance';
const start=new Date().getFullYear()-(new Date().getMonth()<8?1:0);const years=Array.from({length:5},(_,i)=>`${start+1-i}-${start+2-i}`);const academicYear=ref(`${start}-${start+1}`);
const question=ref('');const turns=ref([]);const documents=ref([]);const asking=ref(false);const loadingDocs=ref(false);const error=ref('');const directoryError=ref('');const source=ref(null);const sourceVisible=ref(false);let version=0,docsVersion=0;
const samples=['志愿服务需要哪些证明？','竞赛成果的有效期如何确定？'];
function safeHttps(value){try{const url=new URL(value);return url.protocol==='https:'&&!url.username&&!url.password;}catch{return false;}}
function openSource(doc){if(doc){source.value=doc;sourceVisible.value=true;}}
async function loadDocuments(){const current=++docsVersion;loadingDocs.value=true;directoryError.value='';documents.value=[];try{const result=await getPolicies({academicYear:academicYear.value});if(current===docsVersion)documents.value=result.items;}catch(err){if(current===docsVersion)directoryError.value=err.message||'制度目录加载失败，请刷新重试';}finally{if(current===docsVersion)loadingDocs.value=false;}}
function clearConversation(){version++;turns.value=[];question.value='';error.value='';asking.value=false;sourceVisible.value=false;source.value=null;}
function changeYear(){clearConversation();loadDocuments();}
async function ask(){if(asking.value||!question.value.trim())return;const current=++version;const input=question.value.trim();const year=academicYear.value;asking.value=true;error.value='';try{const result=await askGuidance({question:input,academicYear:year,history:turns.value.slice(-6).map(turn=>turn.question)});if(current===version&&academicYear.value===year){turns.value.push({question:input,result});question.value='';}}catch(err){if(current===version)error.value=err.message||'查询失败，请保留问题后重试';}finally{if(current===version)asking.value=false;}}
onMounted(loadDocuments);onBeforeUnmount(()=>{version++;docsVersion++;});
</script>
<style scoped>
.policy-desk{--ink:#203c5c;--muted:#687d95;--line:#dfe8f3;}.policy-toolbar{display:flex;align-items:center;gap:18px;flex-wrap:wrap;padding:18px 22px;margin:20px 0;}.policy-toolbar label{font-size:13px;color:var(--ink);}.policy-toolbar .el-select{width:160px;margin-left:10px;}.policy-toolbar>span{flex:1;font-size:12px;color:var(--muted);line-height:1.8;}.policy-layout{display:grid;grid-template-columns:minmax(0,1fr) 310px;gap:22px;align-items:start;}.conversation{padding:26px;}.desk-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;}.desk-heading h2{font-size:18px;color:var(--ink);margin:0;}.desk-heading>span,.plain-note{font-size:12px;line-height:1.9;color:var(--muted);}.conversation-start{padding:30px 0;border-bottom:1px solid var(--line);}.conversation-start>span{font-size:11px;color:#2780ce;}.conversation-start h3{font:600 24px/1.6 'STSong','SimSun',serif;color:var(--ink);margin:10px 0;}.conversation-start p{font-size:13px;color:var(--muted);line-height:1.8;}.conversation-start>div{display:flex;gap:8px;flex-wrap:wrap;}.conversation-start .el-button{margin:0;}.policy-turn{border-top:1px solid var(--line);padding:22px 0;font-size:13px;line-height:1.9;color:var(--ink);}.question-record{font-weight:650;}.question-record>span{display:block;color:var(--muted);font-size:11px;font-weight:400;}.policy-turn>small{color:var(--muted);overflow-wrap:anywhere;}.policy-turn blockquote{padding:18px;margin:15px 0;background:#f4f8fd;border-left:3px solid #287bc8;overflow-wrap:anywhere;}.policy-turn blockquote>div{display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;}.policy-turn blockquote>div span{font-size:11px;color:var(--muted);}.policy-turn blockquote p{white-space:pre-wrap;}.policy-turn footer{font-size:11px;color:var(--muted);}.policy-turn footer .el-button{font-size:11px;}.policy-composer{padding-top:24px;border-top:1px solid var(--line);}.policy-composer>label{display:block;font-size:13px;font-weight:650;color:var(--ink);margin-bottom:12px;}.policy-composer>div:last-child{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-top:15px;}.policy-composer small{font-size:11px;line-height:1.8;color:var(--muted);}.policy-directory{padding:22px;position:sticky;top:20px;}.policy-directory article{padding:22px 0;border-bottom:1px solid var(--line);}.policy-directory article>span,.policy-directory small{display:block;font-size:11px;color:var(--muted);}.policy-directory h3{font-size:15px;line-height:1.7;color:var(--ink);margin:10px 0;}.policy-directory article>p{font-size:12px;color:var(--muted);line-height:1.8;}.policy-directory>.router-link-active,.policy-directory>a{display:block;font-size:12px;margin-top:22px;color:#287bc8;}.source-body{font-size:14px;line-height:2;white-space:pre-wrap;overflow-wrap:anywhere;padding:22px;background:#f4f8fd;margin-top:20px;}a:focus-visible{outline:2px solid #287bc8;outline-offset:3px;}@media(max-width:1000px){.policy-layout{grid-template-columns:minmax(0,1fr);}.policy-directory{position:static;}}@media(max-width:600px){.conversation,.policy-directory{padding:18px 14px;}.policy-toolbar{padding:16px;gap:12px;}.policy-toolbar>span{flex-basis:100%;}.policy-composer>div:last-child{align-items:flex-start;flex-direction:column;}.policy-turn blockquote{padding:14px;}.conversation-start h3{font-size:21px;}}
</style>
